Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
    TypeVariable<?>[] typeParameters = targetType.getTypeParameters();

    if (actualTypeArguments.length != typeParameters.length) {
        return null;
    }

    Map<TypeVariable<?>, Type> typeMap = new HashMap<>();
    for (int i = 0; i < typeParameters.length; i++) {
        typeMap.put(typeParameters[i], actualTypeArguments[i]);
    }

    Class<?>[] resolvedArguments = new Class<?>[typeParameters.length];
    for (int i = 0; i < typeParameters.length; i++) {
        Type argument = typeMap.get(typeParameters[i]);
        if (argument instanceof Class<?>) {
            resolvedArguments[i] = (Class<?>) argument;
        } else if (argument instanceof TypeVariable<?>) {
            TypeVariable<?> tv = (TypeVariable<?>) argument;
            Type bound = tv.getBounds()[0];
            if (bound instanceof Class<?>) {
                resolvedArguments[i] = (Class<?>) bound;
            } else {
                return null; // Could not resolve the type
            }
        } else {
            return null; // Unsupported type
        }
    }

    return resolvedArguments;
}

