Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null) {
        throw new IllegalArgumentException("Input bounds list cannot be null");
    }

    List<Integer> suffixSum = new ArrayList<>();
    long totalSum = 0;
    long currentSuffixSum = 0;

    for (int i = bounds.size() - 1; i >= 0; i--) {
        int value = bounds.get(i);
        if (value < 0) {
            throw new IllegalArgumentException("Bounds list cannot contain negative values");
        }
        totalSum += value;
        currentSuffixSum += value;
        suffixSum.add(0, (int) currentSuffixSum);
    }

    return new Pair<>(suffixSum, totalSum);
}

