private void pop(final String descriptor){
    int offset = 0;
    if (descriptor.charAt(0) == '(') {
        offset = 1;
        while (descriptor.charAt(offset) != ')') {
            offset = popType(descriptor, offset);
        }
        offset++; // skip ')'
    }
    popType(descriptor, offset);
}

private int popType(final String descriptor, int offset) {
    switch (descriptor.charAt(offset)) {
        case 'B':
        case 'C':
        case 'I':
        case 'S':
        case 'Z':
            offset += 1;
            return offset;
        case 'F':
            offset += 1;
            return offset;
        case 'D':
        case 'J':
            offset += 1;
            return offset;
        case 'L':
            while (descriptor.charAt(offset) != ';') {
                offset += 1;
            }
            offset += 1;
            return offset;
        case '[':
            while (descriptor.charAt(offset) == '[') {
                offset += 1;
            }
            if ("BCIDSZF".indexOf(descriptor.charAt(offset)) != -1) {
                offset += 1;
            } else if (descriptor.charAt(offset) == 'L') {
                while (descriptor.charAt(offset) != ';') {
                    offset += 1;
                }
                offset += 1;
            } else if (descriptor.charAt(offset) == '[') {
                offset = popType(descriptor, offset);
            }
            return offset;
        default:
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }
}

