String toString(final char ch) {
    if (ch < 128) {
        return CharacterCache.CACHE[ch];
    }
    return String.valueOf(ch);
}
class CharacterCache {
    static final String[] CACHE = new String[128];
    static {
        for (int i = 0; i < CACHE.length; i++) {
            CACHE[i] = String.valueOf((char) i);
        }
    }
}

